<?php require 'config.php'; $msg='';
$farmers=$pdo->query('SELECT farmer_id,name FROM farmers ORDER BY name')->fetchAll(); $produce=$pdo->query('SELECT produce_id,name FROM produce ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){ $fid=(int)($_POST['farmer_id']??0); $pid=(int)($_POST['produce_id']??0); $qty=(float)($_POST['quantity']??0); $date=$_POST['delivery_date']??date('Y-m-d'); if($fid&&$pid&&$qty>0){$pdo->beginTransaction();$pdo->prepare('INSERT INTO deliveries(farmer_id,produce_id,quantity,delivery_date) VALUES(?,?,?,?)')->execute([$fid,$pid,$qty,$date]);$pdo->prepare('INSERT INTO stock(produce_id,quantity_available) VALUES(?,?) ON DUPLICATE KEY UPDATE quantity_available=quantity_available+VALUES(quantity_available)')->execute([$pid,$qty]);$pdo->commit();$msg='Delivery recorded and stock updated.';}}
$rows=$pdo->query('SELECT d.delivery_id,f.name farmer,p.name produce,d.quantity,d.delivery_date FROM deliveries d JOIN farmers f ON d.farmer_id=f.farmer_id JOIN produce p ON d.produce_id=p.produce_id ORDER BY d.delivery_id DESC')->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><title>Deliveries</title><link rel="stylesheet" href="style.css"></head><body><header><h1>Deliveries</h1><nav><a href="index.php">Dashboard</a><a href="farmers.php">Farmers</a><a href="orders.php">Orders</a><a href="dispatches.php">Dispatches</a><a href="reports.php">Reports</a></nav></header><main><h2>Record Delivery</h2><?=htmlspecialchars($msg)?><form method="post"><label>Farmer<select name="farmer_id" required><option value="">Choose farmer</option><?php foreach($farmers as $f): ?><option value="<?=$f['farmer_id']?>"><?=htmlspecialchars($f['name'])?></option><?php endforeach;?></select></label><label>Produce<select name="produce_id" required><option value="">Choose produce</option><?php foreach($produce as $p): ?><option value="<?=$p['produce_id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></label><label>Quantity (kg)<input type="number" name="quantity" min="0.01" step="0.01" required></label><label>Date<input type="date" name="delivery_date" value="<?=date('Y-m-d')?>"></label><button>Save Delivery</button></form><h2>Delivery Records</h2><table><tr><th>ID</th><th>Farmer</th><th>Produce</th><th>Quantity kg</th><th>Date</th></tr><?php foreach($rows as $r): ?><tr><td><?=$r['delivery_id']?></td><td><?=htmlspecialchars($r['farmer'])?></td><td><?=htmlspecialchars($r['produce'])?></td><td><?=$r['quantity']?></td><td><?=$r['delivery_date']?></td></tr><?php endforeach;?></table></main></body></html>
